#pragma once
/**
 * @file StationSplit.hpp
 * @brief One station's data rows: the measurement update and the column split into the shared border and the local block.
 *
 * A family file of PASS B's station build (card NOM3 step PB1b): the steps of the family in
 * kStationBuildSteps / kStationCarrySteps (network/assembly/StationBuild.hpp), generated by
 * scripts/nom_pb1b_cut.py from the frozen text of networkPassB_'s produce loop.
 */

#include <cstdint>
#include "network/driver/RunTypes.hpp"
#include "network/assembly/ParamInventory.hpp"
#include "network/assembly/Contributions.hpp"
#include "common/EpochMeasurement.hpp"
#include <Eigen/Dense>
#include <map>
#include <vector>

namespace GnssProcessor {

// ---- PASS B station steps, declarations (card NOM3 step PB1b; generated by scripts/nom_pb1b_cut.py) ----

struct StationBuild;                       // network/assembly/StationBuild.hpp (card NOM3 step PB1b)
struct StationCarryFrame;                  // network/assembly/StationBuild.hpp
enum class StationStep : std::uint8_t;     // network/assembly/StationBuild.hpp
class GnssConfig;
class NetworkEstimator;
class SphericalHarmonicIonosphere;
class GlobalIonosphereMap;
struct GlobalVtecShConfig;

/**
 * @brief The station's measurement update and its data rows (the split).
 *
 * Step `data_rows` of kStationBuildSteps (network/assembly/StationBuild.hpp); its kinds: DataCode,
 * DataCodeCompanion, DataPhase, DataPhaseSecond. Records: h2local, n_data_rows, param_inv; Done
 * on empty innovations or an H/state mismatch (empty_innov, state_mismatch). The frozen text of
 * networkPassB_'s produce loop below its bindings (card NOM3 step PB1b).
 * @param build One station's build: the station and its slot writable, the run read only.
 * @return StationStep::Done on empty innovations or an H/state mismatch, else
 * StationStep::Next.
 */
StationStep networkStationDataRows(StationBuild& build);

/**
 * @brief Column-split helper: split station @p st's H into the shared
 *        border @p A_s (clock/phase-bias/code-bias columns) and the local
 *        nuisance block @p A_r (decomposition INC-7).
 *
 * Fills the H-column → A_r-column map @p h2local and, per state column, the
 * disposition it took (@p col_disp: border, local block, held coordinate,
 * held at its seed by @p ifb_rule, or unobserved), which the parameter
 * inventory records (card NOM N1).  Throws (linearity invariant) if a
 * position column ever survives into A_r; the per-station try/catch of the
 * PASS-B produce loop catches the throw.  Implemented in
 * @c ApplicationNetworkAssembly.cpp.
 *
 * @param ifb_rule The run's receiver IFB rule (@c ctx.param_inventory.rx_ifb,
 *                 built once per run by @c networkRxIfbRule): which receiver
 *                 IFB columns are left out of the local block.
 * @param[out] tags One contribution tag per data row (card NOM N2a): @c DataCode or
 *                 @c DataPhase with the row's satellite and signal
 *                 (@c tagDataRows), changed to @c DataCodeCompanion or
 *                 @c DataPhaseSecond by the weight pass that scales the row, so a
 *                 tag and a weight cannot disagree.
 *
 * Card NOM3 step PB1b: a free function (formerly Application::networkSplitStation_), so the station
 * steps in the family files can call it; @p config_ is the run's configuration.
 */
void networkSplitStation(const GnssConfig& config_, NetStation& st, const NetworkEstimator& est,
                         const EpochMeasurement& em, const RxIfbRule& ifb_rule,
                         Eigen::MatrixXd& A_s, Eigen::MatrixXd& A_r, Eigen::VectorXd& w,
                         Eigen::VectorXd& y, std::map<int, int>& h2local,
                         std::vector<ParamDisposition>& col_disp, std::vector<RowTag>& tags);

// ---- End of the PASS B station steps, declarations (card NOM3 step PB1b) ----

} // namespace GnssProcessor
